require("dotenv").config();

const { WebClient } = require("@slack/web-api");
const fs = require("fs");
const path = require("path");

const slack = new WebClient(process.env.SLACK_BOT_TOKEN);

const CHANNEL_ID = process.env.SLACK_CHANNEL_ID;

const TICKETS_FILE = path.join(
  __dirname,
  "..",
  "..",
  "data",
  "notion-completed-tickets.json"
);

async function main() {
  try {
    console.log("🤖 Starting Notion → Slack approval flow...");

    // -----------------------------------------
    // 1. Load tickets generated by Notion script
    // -----------------------------------------

    if (!fs.existsSync(TICKETS_FILE)) {
      throw new Error(
        "notion-completed-tickets.json not found. Run get-notion-completed-tickets.js first."
      );
    }

    const tickets = JSON.parse(
      fs.readFileSync(TICKETS_FILE, "utf8")
    );

    if (!tickets.length) {
      throw new Error("No completed tickets found.");
    }

    console.log(
      `📋 Loaded ${tickets.length} tickets from Notion.`
    );

    // -----------------------------------------
    // 2. Create Slack checkbox options
    // -----------------------------------------

    const checkboxOptions = tickets.map((ticket) => ({
      text: {
        type: "plain_text",
        text: `${ticket.priority || "NO PRIORITY"} | ${ticket.id} | ${ticket.title}`.substring(
          0,
          75
        ),
      },
      value: ticket.id,
    }));

    // -----------------------------------------
    // 3. Send Slack approval message
    // -----------------------------------------

    const response = await slack.chat.postMessage({
      channel: CHANNEL_ID,

      text: "AI Automation Agent - Select tickets",

      blocks: [
        {
          type: "header",
          text: {
            type: "plain_text",
            text: "🤖 AI Automation Agent",
          },
        },

        {
          type: "section",
          text: {
            type: "mrkdwn",
            text:
              "*Select the completed Notion tickets you want to automate:*",
          },
        },

        {
          type: "divider",
        },

        {
          type: "actions",
          elements: [
            {
              type: "checkboxes",
              action_id: "selected_tickets",

              options: checkboxOptions,
            },
          ],
        },

        {
          type: "actions",
          elements: [
            {
              type: "button",

              text: {
                type: "plain_text",
                text: "Approve Selected Tickets",
              },

              style: "primary",

              action_id: "approve_tickets",

              value: "approve",
            },
          ],
        },
      ],
    });

    console.log("\n✅ Slack approval message created.");

    console.log(
      `Message TS: ${response.ts}`
    );

    console.log(
      "\n⚠️ Important:"
    );

    console.log(
      "The Slack message has been sent."
    );

    console.log(
      "Next we will connect the button click handler."
    );

  } catch (error) {
    console.error(
      "\n❌ Failed to create Slack approval."
    );

    console.error(
      error.data?.error ||
      error.message ||
      error
    );

    process.exit(1);
  }
}

main();